#include "License.h"
#include "PublicKey.h"   // generated by `brl_keygen genkeys` – holds kPublicKey

namespace brl::License
{
static File keyFile() { return getUserDataDir().getChildFile ("license.key"); }

String sign (const RSAKey& privateKey, const String& email, const String& orderId)
{
    auto payload = String (kPayloadPrefix) + email.trim() + "|" + orderId.trim();
    MemoryBlock mb (payload.toRawUTF8(), payload.getNumBytesAsUTF8());
    BigInteger v;
    v.loadFromMemoryBlock (mb);
    privateKey.applyToValue (v);
    auto out = v.toMemoryBlock();
    return "BRL-" + out.toBase64Encoding();
}

Info verifyWith (const RSAKey& publicKey, const String& keyIn)
{
    Info info;
    auto key = keyIn.removeCharacters (" \t\r\n");
    if (! key.startsWith ("BRL-")) return info;
    MemoryBlock mb;
    if (! mb.fromBase64Encoding (key.substring (4)) || mb.getSize() < 16) return info;
    BigInteger v;
    v.loadFromMemoryBlock (mb);
    publicKey.applyToValue (v);
    auto plain = v.toMemoryBlock();
    auto text = String::fromUTF8 ((const char*) plain.getData(), (int) plain.getSize()).trimCharactersAtEnd (String::charToString (0));
    if (! text.startsWith (kPayloadPrefix)) return info;
    auto parts = StringArray::fromTokens (text.substring (String (kPayloadPrefix).length()), "|", {});
    if (parts.size() != 2 || ! parts[0].containsChar ('@')) return info;
    info.valid = true;
    info.email = parts[0];
    info.orderId = parts[1];
    return info;
}

Info verify (const String& key) { return verifyWith (RSAKey (kPublicKey), key); }

Info current()
{
    auto f = keyFile();
    return f.existsAsFile() ? verify (f.loadFileAsString()) : Info {};
}

String activate (const String& key)
{
    auto info = verify (key);
    if (! info.valid) return "That license key isn't valid. Paste the whole key from your purchase email.";
    if (! keyFile().replaceWithText (key.trim())) return "Couldn't save the license file.";
    return {};
}

void deactivate() { keyFile().deleteFile(); }
}
